import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CfmR1glF.js";const p=JSON.parse('{"title":"架构与边界","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),d={name:"guide/architecture.md"};function m(h,t,n,s,c,i){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="架构与边界" tabindex="-1">架构与边界 <a class="header-anchor" href="#架构与边界" aria-label="Permalink to &quot;架构与边界&quot;">​</a></h1><p>ASAM UI 基于 Vue 3 和 Element Plus，提供统一样式的基础控件、通用复合组件与数据驱动能力。 页面把数据、接口函数、列定义和事件处理传入组件，组件负责通用展示、交互与数据装配。</p><h2 id="组件如何分层" tabindex="-1">组件如何分层 <a class="header-anchor" href="#组件如何分层" aria-label="Permalink to &quot;组件如何分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>职责</th><th>阅读入口</th></tr></thead><tbody><tr><td>设计系统</td><td>tokens、主题变量、基础样式与动效约定</td><td><a href="/guide/theme.html">主题</a></td></tr><tr><td>基础控件</td><td>输入、选择、日期时间等通用交互</td><td><a href="/components.html">组件目录</a></td></tr><tr><td>复合组件</td><td>表单布局、卡片、表格与分页</td><td><a href="/components.html">组件目录</a></td></tr><tr><td>数据驱动</td><td>远程选项、字典、分页请求、表单依赖</td><td><a href="/guide/data-driven.html">数据驱动</a></td></tr><tr><td>容器与反馈</td><td>弹框、抽屉、浮层与下拉菜单</td><td><a href="/components.html">组件目录</a></td></tr></tbody></table><p>层次描述组件职责。实际可用能力以当前版本的官网组件正文、公开类型和完整可运行示例为准。 目录链接、API 表头或一次挂载不能证明某个具体功能已经实现。</p><h2 id="包与宿主" tabindex="-1">包与宿主 <a class="header-anchor" href="#包与宿主" aria-label="Permalink to &quot;包与宿主&quot;">​</a></h2><p><code>@asam-ui/ui</code> 提供通用组件、tokens 和数据运行时。核心包不引用业务仓库别名、业务模型、 store 或具体 API。<code>@asam-ui/ui-yudao</code> 是可选的芋道 adapter，以 provider 注入方式复用 宿主的请求与字典能力。</p><p>业务宿主负责路由、权限、身份凭据、具体接口和业务流程。容器里的提交动作、失败提示与 页面状态仍由宿主按接口约定处理。接入步骤见<a href="/guide/installation.html">安装与消费</a>。</p><h2 id="文档分工" tabindex="-1">文档分工 <a class="header-anchor" href="#文档分工" aria-label="Permalink to &quot;文档分工&quot;">​</a></h2><p>官网独立承载组件正文、API、可运行示例与源码面板。每个重要使用方式由对应组件页说明， TS 与 JS 变体均展示实际运行的完整 SFC；包含辅助脚本或样式时按文件展示、逐文件复制。 语言切换会重新挂载对应变体，状态重置。安装、provider 和主题指南复用同源文档。 Storybook 仅用于本机与内网开发验证。</p><p>API 的可导入类型视图保留联合分支、泛型约束和 events、slots、expose 的 payload。 嵌套参数的可读视图区分 ASAM 声明、上游声明和数据 / provider 协议；说明未声明时明确标识。 固定上游文档默认与注释默认供理解用，实际运行默认优先采用源码或安装包。 显式 <code>undefined</code>、条件表达式、实例工厂和未知默认值各自保留，工厂不会在文档抽取时执行。</p><p>同名正文与演示共用一条目录阅读路径；不同层级和重复标题各有唯一锚点。 目录、API JSON 与示例 JSON 引用同一次构建的公开入口、正文和原始示例文件。</p><h2 id="职责拆分如何阅读" tabindex="-1">职责拆分如何阅读 <a class="header-anchor" href="#职责拆分如何阅读" aria-label="Permalink to &quot;职责拆分如何阅读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>使用目的</th><th>公开承接入口</th><th>需要核对的行为</th></tr></thead><tbody><tr><td>单选 / 多选聚合与显式子项</td><td><a href="/component-AsamRadio.html">AsamRadio</a> / <a href="/component-AsamCheckbox.html">AsamCheckbox</a> / <a href="/component-AsamRadioGroup.html">AsamRadioGroup</a> / <a href="/component-AsamRadioButton.html">AsamRadioButton</a> / <a href="/component-AsamCheckboxGroup.html">AsamCheckboxGroup</a> / <a href="/component-AsamCheckboxButton.html">AsamCheckboxButton</a></td><td>model、禁用、选项与按钮模式</td></tr><tr><td>密码、多行与普通输入</td><td><a href="/component-AsamPassword.html">AsamPassword</a> / <a href="/component-AsamTextarea.html">AsamTextarea</a> / <a href="/component-AsamInput.html">AsamInput</a></td><td>各自输入类型、清除与状态</td></tr><tr><td>日期与范围组合</td><td><a href="/component-AsamDatePicker.html">AsamDatePicker</a> / <a href="/component-AsamDateTimePicker.html">AsamDateTimePicker</a> / <a href="/component-AsamDateTimeRangePicker.html">AsamDateTimeRangePicker</a></td><td>原生 range 与两个 picker 的值模型、边界和事件</td></tr><tr><td>表单布局与动态表单</td><td><a href="/component-AsamBaseForm.html">AsamBaseForm</a> / <a href="/component-AsamFormItem.html">AsamFormItem</a> / <a href="/component-AsamForm.html">AsamForm</a> / <a href="/component-AsamFormSection.html">AsamFormSection</a> / <a href="/component-AsamFormGrid.html">AsamFormGrid</a> / <a href="/component-AsamFormActions.html">AsamFormActions</a></td><td>布局、校验与动态 schema 的实际承接</td></tr><tr><td>原生上传与资源模型</td><td><a href="/component-AsamUpload.html">AsamUpload</a></td><td>对应值模式、transport 和实例入口</td></tr><tr><td>静态层级与远程 / 字典</td><td><a href="/component-AsamCascader.html">AsamCascader</a> / <a href="/component-AsamTreeSelect.html">AsamTreeSelect</a> / <a href="/component-AsamRemoteCascader.html">AsamRemoteCascader</a> / <a href="/component-AsamDictCascader.html">AsamDictCascader</a> / <a href="/component-AsamRemoteTreeSelect.html">AsamRemoteTreeSelect</a> / <a href="/component-AsamDictTreeSelect.html">AsamDictTreeSelect</a></td><td>native / value / object 与数据源协议；完整树和 lazy 以对应入口说明为准</td></tr></tbody></table><p>这些名称用于定位职责；完整行为与 TS/JS 示例仍由对应组件正文提供，不将拆分名称计为功能通过。</p><h2 id="依据与范围" tabindex="-1">依据与范围 <a class="header-anchor" href="#依据与范围" aria-label="Permalink to &quot;依据与范围&quot;">​</a></h2><p>本页依据仓库 <code>docs/ASAM_UI_ARCHITECTURE.md</code> 第 2–3、6、8 节及 <code>docs/ASAM_UI_REPOSITORY_AND_DELIVERY.md</code> 的包职责整理。方案用于解释设计方向， 组件是否可用以当前目录及其对应文档版本为准。当前为本地构建，未包含部署或公开访问。</p>',17)])])}const A=a(d,[["render",m]]);export{p as __pageData,A as default};
